<script setup lang="ts">
import { computed, onMounted, reactive, ref } from "vue";
import { api, ApiError } from "../api";
import type { Contract, ExpenseCategory, Lookups, Supplier } from "../types";
const props=defineProps<{lookups:Lookups|null}>(); const rows=ref<Contract[]>([]),suppliers=ref<Supplier[]>([]),categories=ref<ExpenseCategory[]>([]),showForm=ref(false),error=ref(""),editing=ref<Contract|null>(null);
const form=reactive({contract_no:"",name:"",supplier:"",category:"",department:"",owner:"",status:"draft",start_date:"",end_date:"",amount:"",renewal_notice_days:30,auto_renew:false,kingdee_code:"",external_id:"",notes:""});
const due=computed(()=>rows.value.filter(x=>x.status==='active'&&x.days_to_expiry!==null&&x.days_to_expiry<=x.renewal_notice_days));
async function load(){try{[rows.value,suppliers.value,categories.value]=await Promise.all([api<Contract[]>("/contracts/"),api<Supplier[]>("/suppliers/"),api<ExpenseCategory[]>("/expense-categories/")])}catch(err){error.value=err instanceof ApiError?err.message:"合同暂时无法加载。"}}
function openForm(item?:Contract){editing.value=item||null;Object.assign(form,item?{contract_no:item.contract_no,name:item.name,supplier:item.supplier||"",category:item.category||"",department:item.department||"",owner:item.owner||"",status:item.status,start_date:item.start_date||"",end_date:item.end_date||"",amount:item.amount,renewal_notice_days:item.renewal_notice_days,auto_renew:item.auto_renew,kingdee_code:item.kingdee_code,external_id:item.external_id,notes:item.notes}:{contract_no:"",name:"",supplier:"",category:"",department:"",owner:"",status:"draft",start_date:"",end_date:"",amount:"",renewal_notice_days:30,auto_renew:false,kingdee_code:"",external_id:"",notes:""});showForm.value=true}
async function create(){try{await api(editing.value?`/contracts/${editing.value.id}/`:"/contracts/",{method:editing.value?"PATCH":"POST",body:JSON.stringify({...form,supplier:form.supplier?Number(form.supplier):null,category:form.category?Number(form.category):null,department:form.department?Number(form.department):null,owner:form.owner?Number(form.owner):null,start_date:form.start_date||null,end_date:form.end_date||null})});showForm.value=false;await load()}catch(err){error.value=err instanceof ApiError?Object.values(err.errors).flat().join(" ")||err.message:"合同未保存。"}}
function money(v:string|number){return `¥${Number(v).toLocaleString("zh-CN",{minimumFractionDigits:2})}`};onMounted(load);
</script>
<template><div class="page module-page admin-module-page"><header class="page-intro"><div><p class="eyebrow">合同与周期事项</p><h1>合同履约与到期提醒</h1><p>供应商、费用科目、负责人和外部系统编码统一留档。</p></div><div class="page-actions"><button class="primary-button" @click="showForm=true">登记合同</button></div></header><section class="admin-kpi-strip"><div><span>履行中合同</span><strong>{{rows.filter(x=>x.status==='active').length}}</strong></div><div><span>临近到期</span><strong>{{due.length}}</strong></div><div><span>合同总额</span><strong class="money-kpi">{{money(rows.filter(x=>x.status==='active').reduce((s,x)=>s+Number(x.amount),0))}}</strong></div></section><div v-if="error" class="error-block">{{error}}</div><section class="contract-grid"><article v-for="item in rows" :key="item.id" :class="{due:item.days_to_expiry!==null&&item.days_to_expiry<=item.renewal_notice_days&&item.status==='active'}"><header><span class="record-status" :data-status="item.status">{{item.status_label}}</span><small>{{item.contract_no}}</small></header><h2>{{item.name}}</h2><p>{{item.supplier_name||'未设置供应商'}} · {{item.category_name||'未设置费用类别'}}</p><div class="contract-amount">{{money(item.amount)}}</div><dl><div><dt>履约期间</dt><dd>{{item.start_date||'—'}} 至 {{item.end_date||'—'}}</dd></div><div><dt>负责人</dt><dd>{{item.owner_name||'未设置'}}</dd></div><div><dt>归属部门</dt><dd>{{item.department_name||'未设置'}}</dd></div></dl><footer><span v-if="item.days_to_expiry!==null">{{item.days_to_expiry<0?`已到期 ${-item.days_to_expiry} 天`:`距到期 ${item.days_to_expiry} 天`}}</span><span v-else>未设置到期日</span><span>{{item.auto_renew?'自动续签':'不自动续签'}}</span></footer></article><div v-if="!rows.length" class="empty-state large">还没有合同记录。</div></section><div v-if="showForm" class="modal-backdrop" @click.self="showForm=false"><form class="modal-panel admin-form-modal" @submit.prevent="create"><header><div><p class="eyebrow">合同台账</p><h2>登记行政合同</h2></div><button type="button" class="icon-button" @click="showForm=false">×</button></header><div class="form-grid"><label><span>合同编号</span><input v-model="form.contract_no" required/></label><label><span>合同名称</span><input v-model="form.name" required/></label><label><span>供应商</span><select v-model="form.supplier"><option value="">未设置</option><option v-for="x in suppliers" :key="x.id" :value="x.id">{{x.name}}</option></select></label><label><span>费用类别</span><select v-model="form.category"><option value="">未设置</option><option v-for="x in categories" :key="x.id" :value="x.id">{{x.name}}</option></select></label><label><span>归属部门</span><select v-model="form.department"><option value="">未设置</option><option v-for="x in lookups?.departments||[]" :key="x.id" :value="x.id">{{x.name}}</option></select></label><label><span>负责人</span><select v-model="form.owner"><option value="">未设置</option><option v-for="x in lookups?.users||[]" :key="x.id" :value="x.id">{{x.display_name}}</option></select></label><label><span>开始日期</span><input v-model="form.start_date" type="date"/></label><label><span>结束日期</span><input v-model="form.end_date" type="date"/></label><label><span>合同金额</span><input v-model="form.amount" type="number" min="0" step="0.01" required/></label><label><span>到期提前提醒</span><input v-model.number="form.renewal_notice_days" type="number" min="1"/><small>天</small></label><label><span>状态</span><select v-model="form.status"><option value="draft">草稿</option><option value="active">履行中</option><option value="completed">已完成</option><option value="terminated">已终止</option></select></label><label class="checkbox-label"><input v-model="form.auto_renew" type="checkbox"/><span>自动续签</span></label><label><span>金蝶编码</span><input v-model="form.kingdee_code"/></label><label><span>预算系统标识</span><input v-model="form.external_id"/></label><label class="wide"><span>备注</span><textarea v-model="form.notes"></textarea></label></div><button class="primary-button full">保存合同</button></form></div></div></template>
